import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';
import {createRaveldex,RaveldexError} from '@vmitsaras/raveldex';
import {createEnglishAnalyzer,ENGLISH_ANALYZER} from '@vmitsaras/raveldex-english';
import {createEnglishAnalyzer as fromCore,ENGLISH_ANALYZER as coreDescriptor} from '@vmitsaras/raveldex/integrations/languages/english';
import {createSourceProvider,createSourcePhrases} from '@vmitsaras/raveldex/addons/phrases';import {createPositionProvider} from '@vmitsaras/raveldex/addons/positions';import {createPositionPhrases} from '@vmitsaras/raveldex/addons/phrases/positions';import {createMatchEvidence} from '@vmitsaras/raveldex/addons/evidence';import {createSnapshots,createSnapshotRaveldex,currentNodeSnapshotEnvironment} from '@vmitsaras/raveldex/adapters/snapshots';
assert.deepEqual(ENGLISH_ANALYZER,coreDescriptor);assert.deepEqual(createEnglishAnalyzer().manifest,fromCore().manifest);
const records=[{id:'a',text:{title:'😀 Running searches'}},{id:'b',text:{title:'ran searching'}},{id:'c',text:{title:'agreed documents'}},{id:'d',text:{title:'café source'}}],schema={text:{title:{}}},config=factory=>({schema,analyzer:ENGLISH_ANALYZER,addons:[factory()]});
const external=createRaveldex(config(createEnglishAnalyzer)),convenience=createRaveldex(config(fromCore));let comparisons=0;
try{for(const e of[external,convenience])await e.addMany(records);for(const[text,expected]of[['run search',['a']],['searching',['a','b']],['agreed',['c']],['agre',[]],['cafe',[]],['café',['d']]])for(const page of[{limit:100},{limit:0},{offset:1,limit:1}]){const actual=await external.search(text,page),other=await convenience.search(text,page);assert.deepEqual(actual,other);if(page.limit===100)assert.deepEqual(actual.hits.map(h=>h.id).sort(),expected);comparisons++;}await external.replace({id:'a',text:{title:'walking archives'}});assert.equal((await external.search('run search')).total,0);await external.remove('b');assert.equal((await external.search('searching')).total,0);await external.clear();assert.equal((await external.search({kind:'all'})).total,0)}finally{await external.dispose();await convenience.dispose()}
const failures=[],small=createRaveldex({...config(createEnglishAnalyzer),limits:{maxRawTokenCodeUnits:4}});const typed=code=>error=>{assert.ok(error instanceof RaveldexError);assert.equal(error.code,code);failures.push({code,publicCoreError:true});return true};try{await assert.rejects(small.add({id:'a',text:{title:'exceeds'}}),typed('LIMIT_EXCEEDED'));await assert.rejects(small.search('exceeds'),typed('LIMIT_EXCEEDED'));await assert.rejects(small.add({id:'a',text:{title:'\ud800'}}),typed('INVALID_RECORD'));const controller=new AbortController();controller.abort();await assert.rejects(small.search('run',{signal:controller.signal}),typed('CANCELLED'));assert.equal((await small.search({kind:'all'})).revision,0)}finally{await small.dispose()}
const phrase=text=>({kind:'extension',capability:'phrases',version:1,payload:{text,fields:['title']}}),qualification={profileId:'rx-a040-standalone-independent',scope:'exact-node-runtime',environment:currentNodeSnapshotEnvironment(),evidence:['Independent local standalone interoperability fixture only; no cross-host claim']};const observations=[];
for(const representation of['source','positions']){const providers=()=>[createSourceProvider({fields:['title']}),...(representation==='source'?[createSourcePhrases({fields:['title']})]:[createPositionProvider({fields:['title'],offsets:['title']}),createPositionPhrases({fields:['title']})]),createMatchEvidence({fields:{title:representation==='source'?'source':'offsets'}})];const donor=createSnapshotRaveldex({schema,analyzer:ENGLISH_ANALYZER,addons:[createEnglishAnalyzer(),...providers()]},{nativeQualification:qualification}),target=createSnapshotRaveldex({schema,analyzer:ENGLISH_ANALYZER,addons:[fromCore(),...providers()]},{nativeQualification:qualification});try{await donor.add({id:'a',text:{title:'😀 Running searches'}});const options={extensions:{'match-evidence':{ids:['a'],fields:['title']}}},before=await donor.search(phrase('run search'),options);assert.deepEqual(before.extensions['match-evidence'].documents[0].ranges.map(r=>({start:r.start,end:r.end,term:r.term})),[{start:3,end:10,term:'run'},{start:11,end:19,term:'search'}]);for(const format of['Source','Native']){const encoded=await createSnapshots(donor)['export'+format]();await createSnapshots(target).restore(encoded);const after=await target.search(phrase('run search'),options);assert.deepEqual(after.hits,before.hits);assert.deepEqual(after.extensions['match-evidence'].documents,before.extensions['match-evidence'].documents);observations.push({representation,format,completeHitsAndOriginalRanges:'Pass'})}}finally{await donor.dispose();await target.dispose()}}
for(const specifier of['@vmitsaras/raveldex-english/stem','@vmitsaras/raveldex-english/dist/index.js'])await assert.rejects(import(specifier),{code:'ERR_PACKAGE_PATH_NOT_EXPORTED'});
const report={status:'Pass',comparisons,typedCoreFailures:failures,canonicalFactoryAndDescriptorParity:'Pass',crossPackageSourceNativeRoundtrips:observations,privateDeepImports:'Refused'};await writeFile('/tmp/raveldex-rx-a040-standalone-runtime.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));

